const page=document.body.dataset.page;
const allHouses=projects.filter(p=>!p.slug.startsWith('banya'));
const featured=['komfort-8h10','individualnost-8h11','buduschee-8-5h12'].map(s=>projects.find(p=>p.slug===s));
const houseUrl=p=>'house.html?project='+encodeURIComponent(p.slug)+'&v=8';
const shortTitle=p=>p.title.replace(/^Фокус на /,'');
const titleParts=p=>{const n=shortTitle(p),i=n.search(/\d/);return i<0?[n,'']: [n.slice(0,i).trim(),n.slice(i)];};
const familyKey=p=>p.series||p.slug;
const familyModels=p=>{const variants=allHouses.filter(v=>familyKey(v)===familyKey(p));return variants.length?variants:[p];};
const bedrooms=n=>n+' '+(n%100>=11&&n%100<=14?'спален':n%10===1?'спальня':n%10>=2&&n%10<=4?'спальни':'спален');
const modelSize=p=>p.size||'Размер уточняется';
function groupHouseModels(matches,order='default'){
 const groups=new Map();for(const p of matches){const key=familyKey(p);if(!groups.has(key))groups.set(key,{key,name:p.series||p.title,variants:familyModels(p),matches:[]});groups.get(key).matches.push(p);}
 const compare=order==='price'?(a,b)=>(a.price??Infinity)-(b.price??Infinity):order==='area'?(a,b)=>a.area-b.area:null;
 const result=[...groups.values()].map(group=>{const preferred=featured.find(v=>familyKey(v)===group.key&&group.matches.some(m=>m.slug===v.slug));const model=compare?[...group.matches].sort(compare)[0]:preferred||group.matches[0];return {...group,model};});
 if(compare)result.sort((a,b)=>compare(a.model,b.model));return result;
}
function renderProjectCard(p,family=null){const [name,size]=titleParts(p),many=family&&family.variants.length>1;return `<article class="project-card" ${family?`data-family="${esc(family.key)}" data-project="${esc(p.slug)}"`:''}><a class="project-img" href="${houseUrl(p)}"><img src="${p.image}" alt="${esc(p.title)}, визуализация" loading="lazy" width="640" height="520"><span class="project-badge">${many?family.variants.length+' '+(family.variants.length<5?'варианта':'вариантов'):p.floors===1?'Один этаж':'Два этажа'}</span></a><div class="project-info"><h3><a href="${houseUrl(p)}">${family?esc(family.name):`<span>Фокус на ${esc(name)}</span>${esc(size||name)}`}</a></h3>${family?`<p class="family-model-caption">Вариант: ${esc(modelSize(p))}</p>`:''}<div class="project-specs"><span>${area(p.area)}</span><span>${bedrooms(p.bed)}</span><span>${p.baths} ${p.baths===1?'санузел':'санузла'}</span></div>${family&&family.matches.length<family.variants.length?`<p class="family-match-caption">Под ваши условия: ${family.matches.length} из ${family.variants.length} вариантов</p>`:''}<div class="project-price"><div><strong>${money(p.price)}</strong><small>${p.price==null?'Стоимость уточнит менеджер':family?'В комплектации показанного варианта':'В комплектации проекта'}</small></div><a href="${houseUrl(p)}" aria-label="${many?'Выбрать вариант: ':'Посмотреть '}${esc(family?family.name:p.title)}">${arrow}</a></div></div></article>`;}
function card(p){return renderProjectCard(p);}
function familyCard(group){return renderProjectCard(group.model,group);}
function modelSelector(p){const variants=familyModels(p);if(variants.length<2)return '';return `<nav class="model-selector" aria-label="Размер и планировка дома"><h2>Размер и планировка</h2><div class="model-choices">${variants.map(v=>`<a class="model-option" href="${houseUrl(v)}#model" ${v.slug===p.slug?'aria-current="page"':''}><strong>${esc(modelSize(v))}</strong><small>${area(v.area)} · ${bedrooms(v.bed)}</small>${v.slug===p.slug?'<span class="model-current" aria-hidden="true">✓</span>':''}</a>`).join('')}</div><p>Дополнительные работы выбираются для каждого варианта отдельно.</p></nav>`;}
const brand=`<span class="brand-symbol" aria-hidden="true"></span><span><strong>FOCUS HOUSE</strong><small>Каркасные дома для жизни</small></span>`;
const nav=[['projects','projects.html?v=8','Проекты'],['kit','kit.html?v=8','Комплектация'],['built','built.html?v=8','Построенные дома'],['company','company.html?v=8','О компании'],['contacts','contacts.html?v=8','Контакты']];
function header(){return `<a href="#main" class="skip">К содержанию</a><header class="header"><div class="container header-inner"><a class="brand" href="index.html?v=8" aria-label="Focus House, главная">${brand}</a><nav class="nav" id="navigation" aria-label="Основное меню">${nav.map(([id,url,label])=>`<a href="${url}" ${page===id?'aria-current="page"':''}>${label}<span aria-hidden="true">${arrow}</span></a>`).join('')}</nav><div class="header-actions"><span class="header-place">Москва и область</span><a class="header-projects" href="projects.html?v=8">Проекты домов</a><button class="btn consult-btn" data-consult>Обсудить дом</button><button class="icon-btn menu-toggle" aria-label="Открыть меню" aria-expanded="false" aria-controls="navigation"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h4v4H3zm7 0h4v4h-4zm7 0h4v4h-4zM3 10h4v4H3zm7 0h4v4h-4zm7 0h4v4h-4zM3 17h4v4H3zm7 0h4v4h-4zm7 0h4v4h-4z"/></svg></button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div><a class="brand" href="index.html?v=8">${brand}</a><p>Продуманные каркасные дома для жизни за городом. Москва и Московская область.</p></div><div class="footer-links"><h3>Выбрать дом</h3>${nav.slice(0,3).map(n=>`<a href="${n[1]}">${n[2]}</a>`).join('')}</div><div class="footer-links"><h3>Обсудить строительство</h3><a href="company.html?v=8">О компании и процессе</a><a href="contacts.html?v=8">Контакты</a><button class="btn white compact" data-consult>Получить консультацию</button></div></div><div class="footer-bottom"><span>© Focus House</span><span>Дизайн-концепция. Цены и спецификации требуют подтверждения.</span><a href="ui.html?v=8">Правила интерфейса</a><a href="../design/">Первая концепция</a></div></div></footer>`;}
function crumbs(label){return `<div class="container breadcrumb"><a href="index.html?v=8">Главная</a><span>/</span><span>${esc(label)}</span></div>`;}
function sectionHead(title,text='',link=''){const pairs={'Пространство для вашей семьи':['Пространство','для вашей семьи'],'Что входит в стоимость':['Что входит','в стоимость'],'Под ваш образ жизни':['Под ваш','образ жизни'],'Другие проекты для вашей семьи':['Другие проекты','для вашей семьи'],'Система, в которой важны детали':['Система,','в которой важны детали'],'Спецификация на примере проекта':['Спецификация','на примере проекта']};return `<div class="section-head"><div>${pairs[title]?archHeading(...pairs[title]):`<h2>${title}</h2>`}${text?`<p>${text}</p>`:''}</div>${link}</div>`;}
function requestForm(id){return `<form class="request-form" data-form="${id}" novalidate><div class="form-context" hidden></div><div class="field"><label for="${id}-phone">Телефон <span aria-hidden="true">*</span></label><input id="${id}-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+7 (___) ___-__-__" required aria-describedby="${id}-phone-error"><p class="error" id="${id}-phone-error" hidden></p></div><div class="field"><label for="${id}-name">Как к вам обращаться</label><input id="${id}-name" name="name" autocomplete="given-name" placeholder="Ваше имя"></div><details class="optional-comment"><summary>Добавить пожелания</summary><div class="field"><label for="${id}-comment">Что хотите обсудить</label><textarea id="${id}-comment" name="comment" placeholder="Проект, участок или вопросы о строительстве"></textarea></div></details><label class="check-label"><input name="consent" type="checkbox" required aria-describedby="${id}-consent-error"><span>Согласие на обработку данных — место для утверждённого компанией текста и ссылки на политику.</span></label><p class="error consent-error" id="${id}-consent-error" hidden>Отметьте согласие, чтобы продолжить демонстрацию.</p><button class="btn dark" type="submit">Получить консультацию ${arrow}</button><p class="demo-note">Демонстрация формы: данные никуда не отправляются и не сохраняются.</p><div class="form-result" role="status" aria-live="polite"></div></form>`;}
function consultPanel(){return `<section class="container section"><div class="consult-panel"><div>${archHeading('Начнём с вашего','представления о доме')}<p>Обсудим участок, планировку и пожелания. Менеджер поможет выбрать проект и при необходимости подготовит смету.</p></div>${requestForm('consult')}</div></section>`;}
function faq(){return `<section class="container section"><div class="faq"><div>${archHeading('До знакомства','с менеджером')}<p class="muted" style="margin-top:20px">Ответы на вопросы, которые помогают принять решение.</p></div><div>${[['Почему у дома одна цена?','Для каждого проекта предусмотрена единая комплектация. Её состав можно изучить заранее. Дополнительные работы считаются отдельно и согласовываются до включения в договор.'],['Что входит в комплектацию?','Конструктив дома, утепление, кровля, окна и отделка по спецификации проекта. В карточке можно раскрыть полный перечень материалов и работ. Инженерные системы и выбранные дополнительные решения рассматриваются отдельно.'],['Можно ли изменить проект?','Пожелания по планировке, отделке и участку обсудите с менеджером. Возможность изменений, их стоимость и влияние на проект необходимо уточнить до заключения договора.'],['Что происходит после обращения?','Менеджер связывается по телефону, консультирует и уточняет задачу. Если требуется, выполняет расчёт и отправляет смету.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function steps(){return `<div class="steps">${[['Знакомство','Рассказываете, какой дом нужен и где находится участок.'],['Проект и смета','Изучаем пожелания, состав работ и согласовываем стоимость.'],['Строительство','Организуем работы, технический надзор и фотоотчёты.'],['Передача дома','Проверяем результат и проходим приёмку вместе с вами.']].map(([t,p])=>`<article class="step"><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>`;}
function builtCards(full=false){return `<div class="built-grid">${[{img:'built-comfort',title:'Дом по проекту «Комфорт»',text:'Фотография построенного дома из материалов компании.',slug:'komfort-8h12'},{img:'built-space',title:'Дом по проекту «Пространство»',text:'Реализованный проект 8,5×11. Фотография со старого сайта.',slug:'prostranstvo-8-5h11'},...(full?[{img:'built-standard',title:'Дом по проекту «Стандарт»',text:'Реализованный проект 7×8. Фотография со старого сайта.',slug:'standart-7h8'}]:[])].map(x=>`<article class="built-card case-card"><div class="case-visual"><button class="case-image" data-image="media/${x.img}.webp" data-caption="${esc(x.title)}" aria-label="Увеличить фотографию: ${esc(x.title)}"><img src="media/${x.img}.webp" alt="${esc(x.title)}" width="900" height="650" loading="lazy"><span class="case-zoom" aria-hidden="true">${plus}</span></button><div class="case-label glass-panel"><h3>${x.title}</h3><p>Построенный дом Focus House</p></div></div><div class="case-caption"><p>${x.text}</p><a class="text-link" href="house.html?project=${x.slug}&v=8">Смотреть проект ${arrow}</a></div></article>`).join('')}</div>`;}
const pickerHtml=`<section class="container section" id="selection"><div class="picker"><div class="picker-copy">${archHeading('Найдём дом','под вашу жизнь')}<p>Ответьте на три вопроса. Покажем проекты, подходящие по бюджету, этажности и количеству спален.</p><small>Результат сразу после ответов.<br>Телефон для подбора не нужен.</small></div><div class="picker-area" id="picker-area"></div></div></section>`;

function archHeading(lead,tail,tag='h2',cls=''){return `<${tag} class="motion-heading ${cls}" data-heading-reveal><span class="heading-lead">${lead}</span> <span class="heading-tone">${tail}</span></${tag}>`;}
function processBlock(){return `<section class="container section bw-process" id="process"><div class="process-grid node-grid"><div class="process-story"><div class="process-intro grid-cell">${archHeading('От первой встречи —','к вашему готовому дому')}<p>Сначала обсуждаем проект и участок, затем согласовываем состав работ и стоимость. Вы понимаете, что происходит на каждом этапе.</p><a class="text-link" href="company.html?v=8">Подробнее о строительстве ${arrow}</a></div><div class="process-photo grid-cell"><img src="media/built-comfort.webp" alt="Построенный дом Focus House, фотография из материалов компании" width="1024" height="577" loading="lazy"></div></div><ol class="process-stages">${[['Знакомство','Обсуждаем ваши пожелания, проект и участок. Менеджер помогает определить задачу.'],['Проект и смета','Согласовываем планировку, комплектацию, дополнительные работы и стоимость.'],['Строительство','Организуем работы, технический надзор и фотоотчёты о ходе строительства.'],['Передача дома','Проверяем результат по согласованному проекту и проходим приёмку вместе с вами.']].map(([t,d],i)=>`<li class="process-stage grid-cell"><span class="stage-index">#01-${i+1}</span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol></div></section>`;}
function objectMapPanel(){return `<div class="object-map-panel" id="built-map-panel" data-built-panel="map" hidden><div class="map-empty"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M32 57S50 39 50 23a18 18 0 1 0-36 0c0 16 18 34 18 34z"/><circle cx="32" cy="23" r="6"/></svg><h2>Карта построенных домов</h2><p>Здесь появятся объекты Focus House после подключения карты. Пока посмотрите фотографии и проекты построенных домов.</p><button class="btn dark" data-built-view="photos">Смотреть фотографии ${arrow}</button><small>Эскиз раздела. Реальные точки ещё не подключены.</small></div></div>`;}

function home(){const p=projects.find(p=>p.slug==='buduschee-9-5h14');const homeProjects=[...featured,projects.find(p=>p.slug==='prostranstvo-8-5h11')].filter(Boolean);return `<section class="bw-hero-wrap"><div class="bw-hero"><div class="bw-hero-camera"><img class="bw-hero-image" src="${p.image}" alt="${esc(p.title)}, визуализация проекта Focus House" width="1200" height="875" fetchpriority="high"></div><div class="bw-hero-shade"></div>${archHeading('Продуманные','дома для жизни','h1','bw-hero-title')}<div class="bw-hero-bottom"><p>Каркасные дома в Москве и области. Единая комплектация, открытый состав работ и понятная стоимость проекта.</p><div class="actions"><a class="btn bw-primary" href="projects.html?v=8">Посмотреть проекты ${arrow}</a><button class="btn bw-glass" data-consult>Обсудить дом ${arrow}</button></div></div><aside class="bw-hero-cutout glass-panel"><div>${plus}<p>Одна продуманная комплектация</p></div><div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s7-7 7-13a7 7 0 1 0-14 0c0 6 7 13 7 13z"/><circle cx="12" cy="8" r="2"/></svg><p>Москва и Московская область</p></div></aside></div></section><section class="container section bw-project-section" id="projects"><div class="bw-section-head">${archHeading('Выберите дом,','в котором хочется жить')}<a class="btn dark" href="projects.html?v=8">Весь каталог ${arrow}</a></div><div class="showcase" data-showcase><div class="bw-projects" id="home-projects" aria-label="Проекты домов">${homeProjects.map(v=>`<article class="bw-project-card"><a class="bw-project" href="${houseUrl(v)}"><img src="${v.image}" alt="${esc(v.title)}, визуализация" width="1200" height="875" loading="lazy"><div class="project-glass glass-panel"><h3>${esc(v.series||v.title)}</h3><p>${esc(v.size)} · ${area(v.area)} · ${v.bed} спальни</p><span>${v.floors===1?'Один этаж':'Два этажа'}</span></div><div class="project-cutout"><strong>${money(v.price)}</strong><small>В комплектации проекта</small><span class="project-open-label">Смотреть проект ${arrow}</span></div><span class="project-eye" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></span></a></article>`).join('')}</div><div class="showcase-controls" hidden><span class="showcase-count" aria-hidden="true">1–2 / ${homeProjects.length}</span><button class="icon-btn" data-showcase-prev aria-label="Предыдущие проекты" aria-controls="home-projects">${arrow}</button><button class="icon-btn" data-showcase-next aria-label="Следующие проекты" aria-controls="home-projects">${arrow}</button></div></div></section>${pickerHtml}<section class="container section bw-services" id="approach"><div class="service-grid node-grid"><div class="service-intro grid-cell">${archHeading('Одна комплектация.','Всё продумано заранее')}</div><div class="service-aside grid-cell"><p>Материалы, планировка и организация стройки — с понятным составом работ.</p><a class="text-link" href="kit.html?v=8">Что входит в дом ${arrow}</a></div><article class="service-cell grid-cell"><h3>Продуманная комплектация</h3><p>Конструктив, утепление, кровля, окна и отделка. Состав материалов и работ можно изучить до обращения.</p><a class="text-link" href="kit.html?v=8">Изучить комплектацию ${arrow}</a></article><article class="service-cell grid-cell"><h3>Открытая стоимость</h3><p>Одна цена дома в комплектации проекта. Дополнительные работы выбираются и рассчитываются отдельно.</p><a class="text-link" href="projects.html?v=8">Проекты и цены ${arrow}</a></article><article class="service-cell grid-cell"><h3>Ваше пространство</h3><p>Этажность, спальни, общие комнаты и терраса. Выбирайте планировку по тому, как хотите жить.</p><a class="text-link" href="#selection">Подобрать дом ${arrow}</a></article></div></section><section class="container section bw-built" id="real-objects"><div class="bw-section-head">${archHeading('Дома, в которых','уже живут')}<div class="section-actions"><a class="text-link" href="built.html?view=map&v=8">Объекты на карте ${arrow}</a><a class="btn secondary" href="built.html?v=8">Все построенные дома ${arrow}</a></div></div>${builtCards()}</section>${processBlock()}${faq()}${consultPanel()}`;}
function catalog(){return `${crumbs('Проекты домов')}<section class="container"><div class="page-head">${archHeading('Ваш дом','начинается с выбора','h1')}<p>Выберите архитектуру дома, а затем — размер и планировку. Варианты каждого проекта собраны в одной карточке.</p></div><form class="filters" id="filters"><div class="field"><label for="search">Название или размер</label><input id="search" name="q" type="search" placeholder="Например, Комфорт или 8×10"></div><div class="field"><label for="budget">Стоимость до</label><select id="budget" name="budget"><option value="">Без ограничения</option>${[6000000,8000000,10000000,12000000].map(n=>`<option value="${n}">${money(n)}</option>`).join('')}</select></div><div class="field"><label for="floors">Этажей</label><select id="floors" name="floors"><option value="">Любое количество</option><option value="1">Один</option><option value="2">Два</option></select></div><div class="field"><label for="beds">Спален</label><select id="beds" name="beds"><option value="">Любое количество</option><option value="2">Одна или две</option><option value="3">Три</option><option value="4">Четыре и больше</option></select></div><button type="button" class="text-link filter-reset" id="reset-filters" style="border:0;background:none">Сбросить</button></form><div class="result-head"><p id="result-count" role="status" aria-live="polite"></p><div><label class="sr-only" for="sort">Порядок проектов</label><select id="sort"><option value="default">По порядку каталога</option><option value="price">Сначала дешевле</option><option value="area">По возрастанию площади</option></select></div></div><div class="project-grid" id="catalog-results"></div></section>${consultPanel()}`;}
let currentHouse=null,selectedAddons=new Map();
function house(){const slug=new URLSearchParams(location.search).get('project');const p=projects.find(p=>p.slug===slug);if(!p)return `${crumbs('Проект не найден')}<section class="container section"><h1>Такого проекта пока нет</h1><p class="muted" style="margin-top:24px">Вернитесь в каталог, чтобы выбрать актуальный вариант.</p><a class="btn" href="projects.html?v=8" style="margin-top:24px">Перейти в каталог</a></section>`;currentHouse=p;document.title=p.title+' — Focus House';return `<div class="container breadcrumb"><a href="index.html?v=8">Главная</a><span>/</span><a href="projects.html?v=8" id="catalog-back">Проекты</a><span>/</span><span>${esc(shortTitle(p))}</span></div><section class="container"><div class="house-head"><div><div class="gallery-main"><img id="house-main-image" src="${p.image}" alt="${esc(p.title)}, визуализация" width="1000" height="800" fetchpriority="high"><button class="icon-btn" id="expand-house" aria-label="Увеличить изображение дома">${plus}</button></div><div class="gallery-thumbs" aria-label="Ракурсы дома">${p.gallery.map((img,i)=>`<button data-gallery="${img}" aria-pressed="${i===0}" aria-label="Ракурс ${i+1}"><img src="${img}" alt="" width="100" height="80" loading="lazy"></button>`).join('')}</div></div><div class="house-summary" id="model">${archHeading('Фокус на '+esc(titleParts(p)[0]),esc(titleParts(p)[1]||p.size),'h1')}${modelSelector(p)}<dl class="spec-grid"><div><dt>Площадь дома</dt><dd>${area(p.area)}</dd></div><div><dt>Этажей</dt><dd>${p.floors}</dd></div><div><dt>Спален</dt><dd>${p.bed}</dd></div><div><dt>Санузлов</dt><dd>${p.baths}</dd></div><div><dt>Терраса</dt><dd>${p.terrace?area(p.terrace):'По проекту'}</dd></div><div><dt>Размеры</dt><dd>${esc(p.size||'По проекту')}</dd></div></dl><div class="house-price"><strong>${money(p.price)}</strong><p>За дом в комплектации проекта.</p></div><div class="actions"><button class="btn" data-quote>Запросить КП ${arrow}</button><a class="btn secondary" href="#addons">Добавить работы</a></div><p class="small muted" style="margin-top:16px">Участок и дополнительные пожелания уточняем перед подготовкой сметы.</p></div></div><nav class="house-subnav" aria-label="Разделы проекта"><a href="#plans">Планировка</a><a href="#specification">Комплектация</a><a href="#addons">Дополнительные работы</a></nav></section><section class="container section" id="plans">${sectionHead('Пространство для вашей семьи')}<div class="plan-layout"><div class="plan-preview">${p.plans.length?`<div class="tabs" aria-label="Планы этажей">${p.plans.map((v,i)=>`<button data-plan="${i}" aria-pressed="${i===0}">${i+1} этаж</button>`).join('')}</div><img id="plan-image" src="${p.plans[0].img}" alt="${esc(p.plans[0].label)}" width="700" height="500" loading="lazy"><button class="icon-btn" id="expand-plan" aria-label="Увеличить планировку">${plus}</button>`:`<p>Планировку этого проекта предоставит менеджер.</p><button class="btn dark" data-consult style="margin-top:24px">Запросить планировку</button>`}</div><div class="plan-info"><h3>${p.floors===1?'Всё на одном этаже':'Место для общих и личных пространств'}</h3><p>${p.bed} ${p.bed<5?'спальни':'спален'}, ${p.baths} ${p.baths===1?'санузел':'санузла'}${p.terrace?', терраса '+area(p.terrace):''}. Увеличьте план, чтобы рассмотреть расположение комнат и размеры.</p><p>Хотите обсудить изменения? Уточним возможность и состав работ перед расчётом.</p><button class="text-link" data-consult style="border:0;background:none;padding:16px 0">Обсудить планировку ${arrow}</button></div></div></section><section class="container section" id="specification">${sectionHead('Что входит в стоимость','Материалы и решения из спецификации этого проекта.',`<a href="kit.html?v=8" class="text-link">О технологии подробнее ${arrow}</a>`)}<table class="spec-table"><caption class="sr-only">Комплектация ${esc(p.title)}</caption><tbody>${p.kit.map(([n,v],i)=>`<tr ${i>=8?'data-extra-spec hidden':''}><th scope="row">${esc(n)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table><button class="btn secondary" id="expand-spec" aria-expanded="false" style="margin-top:20px">Показать всю комплектацию</button><details style="margin-top:20px"><summary>Организация стройки и включённые услуги</summary><ul class="plain-list">${p.services.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details></section><section class="container section" id="addons">${sectionHead('Под ваш образ жизни','Выберите дополнительные работы. Стоимость проекта и дополнений видна отдельно. Нажмите «?» рядом с услугой, чтобы прочитать пояснение.')}<div class="addons-layout"><div class="addon-groups" id="addon-groups"></div><aside class="estimate" aria-label="Предварительный расчёт"><h3>Ваш расчёт</h3><div class="estimate-row"><span>Дом в комплектации</span><strong>${money(p.price)}</strong></div><div class="estimate-row"><span>Дополнительные работы</span><strong id="addons-total">0 ₽</strong></div><div class="estimate-total"><span class="small">Предварительная сумма</span><strong id="estimate-total">${money(p.price)}</strong></div><p id="estimate-note">Состав и окончательную стоимость работ согласуем по вашему участку.</p><button class="btn" data-quote>Запросить КП по расчёту ${arrow}</button><p>Выбранные работы будут указаны в демонстрации обращения.</p></aside></div></section><section class="container section">${sectionHead('Другие проекты для вашей семьи','Продолжите выбор, сохранив представление о бюджете.',`<a href="projects.html?v=8" class="text-link">Весь каталог ${arrow}</a>`)}<div class="project-grid">${groupHouseModels(allHouses.filter(v=>familyKey(v)!==familyKey(p)&&v.floors===p.floors).sort((a,b)=>Math.abs(a.area-p.area)-Math.abs(b.area-p.area))).slice(0,3).map(familyCard).join('')}</div></section><div class="mobile-cta"><div><small>В комплектации проекта</small><strong>${money(p.price)}</strong></div><button class="btn" data-quote>Запросить КП</button></div>`;}
function kit(){const p=projects.find(p=>p.slug==='buduschee-8-5h12');return `${crumbs('Комплектация и технологии')}<section class="container"><div class="page-head">${archHeading('Продуман каждый слой','вашего дома','h1')}<p>Одна комплектация, которую можно изучить до знакомства с менеджером. Рассказываем, что получаете и как это работает.</p></div><div class="kit-intro"><div>${archHeading('Сначала понятный состав.','Потом решение.')}<p>Конструктив, теплоизоляция, окна и отделка описаны в карточке каждого проекта. Дополнительные работы рассчитываются отдельно.</p><a class="btn" href="projects.html?v=8">Посмотреть проекты ${arrow}</a></div><img src="media/frame.webp" alt="Фотография обвязки дома с пояснениями из материалов компании" width="800" height="700"></div></section><section class="container section">${sectionHead('Система, в которой важны детали')}<div class="included">${[['Каркас','Строганая доска камерной сушки. Сечения элементов указаны для каждого узла в спецификации.'],['Утепление','Толщина и расположение теплоизоляции раскрыты отдельно для стен и перекрытий.'],['Окна','ПВХ-профиль и стеклопакеты по проекту. Характеристики можно проверить в комплектации.'],['Кровля','Металлочерепица и стропильная система. Материал и толщина описаны заранее.'],['Отделка','Материалы фасада, стен, потолков и основания пола перечислены в карточке дома.'],['Контроль','Технический надзор, фотоотчёты и проверка тёплого контура в составе услуг из каталога.']].map(([h,t])=>`<article><h3>${h}</h3><p>${t}</p></article>`).join('')}</div></section><section class="container section">${sectionHead('Спецификация на примере проекта','Ниже — комплектация «Фокус на будущее 8,5×12». Точный состав смотрите в карточке выбранного дома.')}<table class="spec-table"><tbody>${p.kit.map(([a,b])=>`<tr><th scope="row">${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table></section>${faq()}${consultPanel()}`;}
function built(){return `${crumbs('Построенные дома')}<section class="container"><div class="page-head">${archHeading('Дома, в которых','уже идёт жизнь','h1')}<p>Реальные фотографии из материалов Focus House. Рассмотрите результат и перейдите к проекту, который лёг в его основу.</p></div><div class="built-view-controls" role="group" aria-label="Представление построенных домов"><button class="btn dark" data-built-view="photos" aria-pressed="true" aria-controls="built-photos-panel">Фотографии</button><button class="btn secondary" data-built-view="map" aria-pressed="false" aria-controls="built-map-panel">Карта объектов</button></div><div id="built-photos-panel" data-built-panel="photos">${builtCards(true)}</div>${objectMapPanel()}</section>${consultPanel()}`;}
function company(){return `${crumbs('О компании')}<section class="container"><div class="page-head">${archHeading('В фокусе — ваш дом','и весь путь к нему','h1')}<p>Focus House строит каркасные дома в Москве и Московской области. Помогаем разобраться в проекте, работах и стоимости до начала строительства.</p></div><div class="split"><img class="split-img" src="media/built-standard.webp" alt="Построенный дом по проекту Стандарт, фотография из материалов Focus House" width="800" height="700"><div><h2>Понимать, что происходит на стройке</h2><ul class="feature-list"><li><span class="check">✓</span><div><strong>Один контекст для всей команды</strong><p>Проект и пожелания передаются от первого обращения к расчёту и организации работ.</p></div></li><li><span class="check">✓</span><div><strong>Фотоотчёты и технический надзор</strong><p>В составе услуг каталога предусмотрены наблюдение за работами и отчёты о ходе строительства.</p></div></li><li><span class="check">✓</span><div><strong>Проверка перед передачей</strong><p>Результат рассматриваем по согласованному проекту и составу работ.</p></div></li></ul></div></div></section>${processBlock()}<section class="container section"><div class="notice">Для финальной страницы о компании добавим утверждённые сведения о команде, документы и подтверждённые отзывы. В концепции используются только доступные материалы.</div></section>${consultPanel()}`;}
function contacts(){return `${crumbs('Контакты')}<section class="container"><div class="page-head">${archHeading('Обсудим','ваш будущий дом','h1')}<p>Можно прийти с выбранным проектом, планом участка или первым вопросом о строительстве.</p></div><div class="contacts-layout"><div class="contacts-meta"><h3>Focus House</h3><p>Каркасные дома в Москве и Московской области.</p><dl><dt>Как проходит консультация</dt><dd>Менеджер связывается по телефону, уточняет задачу и при необходимости готовит смету.</dd><dt>Телефон, офис и время работы</dt><dd>Добавим после подтверждения компанией.</dd><dt>Реквизиты и документы</dt><dd>Разместим утверждённые данные к запуску.</dd></dl></div><div><h2 style="font-size:32px;margin-bottom:28px">Оставить вопрос</h2>${requestForm('contact')}</div></div></section>`;}
function ui(){return `${crumbs('Правила интерфейса')}<section class="container"><div class="page-head"><h1>Единый язык Focus House</h1><p>Визуальные решения для всех страниц. Рабочая библиотека для согласования и передачи программисту.</p></div><div class="swatches">${[['Forest','#0B2A25'],['Yellow','#FBC001'],['Sage','#609B8E'],['Ink','#13100D'],['White','#FFFFFF']].map(([a,b])=>`<div class="swatch"><div style="background:${b}"></div><p>${a}<br>${b}</p></div>`).join('')}</div><div class="ui-block"><h2>Шрифт Onest</h2><p class="display-sample" style="margin-bottom:24px">Дом продуман до деталей</p><h2>Заголовок раздела</h2><h3 style="margin:24px 0">Заголовок карточки</h3><p>Основной текст: спокойный ритм, читаемые строки и понятные формулировки. На телефоне текст сохраняет размер от 16 пикселей.</p></div><div class="ui-block"><h2>Действия и состояния</h2><div class="ui-row"><button class="btn" data-consult>Получить консультацию ${arrow}</button><a class="btn dark" href="projects.html?v=8">Посмотреть проекты</a><a class="btn secondary" href="kit.html?v=8">Изучить комплектацию</a><button class="btn" disabled>Недоступное действие</button></div></div><div class="ui-block"><h2>Карточки проектов</h2><div class="project-grid">${featured.map(card).join('')}</div></div><div class="ui-block"><h2>Форма и обратная связь</h2><div style="max-width:520px">${requestForm('ui')}</div></div><div class="ui-block"><h2>Принципы адаптации</h2><div class="included"><article><h3>Телефон</h3><p>Одна колонка, доступное меню, крупные действия, последовательное чтение и сводка цены в карточке дома.</p></article><article><h3>Планшет</h3><p>Две колонки для проектов, фильтры перестраиваются, разделы сохраняют порядок.</p></article><article><h3>Компьютер</h3><p>Три проекта в ряд, галерея рядом с параметрами, расчёт допработ рядом со списком.</p></article></div></div></section>`;}
const routes={home,projects:catalog,house,kit,built,company,contacts,ui};
$('#app').innerHTML=header()+`<main id="main">${(routes[page]||home)()}</main>`+footer()+`<dialog id="request-dialog" aria-labelledby="request-title"><button class="icon-btn dialog-close" data-close aria-label="Закрыть форму">×</button><div class="dialog-body"><h2 id="request-title">Обсудим ваш будущий дом</h2><p id="request-description">Менеджер поможет разобраться с проектом и вопросами о строительстве.</p>${requestForm('modal')}</div></dialog><dialog id="image-dialog" class="image-dialog" aria-label="Увеличенное изображение"><button class="icon-btn dialog-close" data-close aria-label="Закрыть изображение">×</button><img alt=""><p></p></dialog>`;
