const toggle=$('.menu-toggle'), navigation=$('#navigation');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');navigation.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){toggle.click();toggle.focus();}});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
let lastTrigger=null;
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{lastTrigger?.focus();});});
function showImage(src,caption,trigger){lastTrigger=trigger;const d=$('#image-dialog');$('img',d).src=src;$('img',d).alt=caption;$('p',d).textContent=caption;d.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(b)showImage(b.dataset.image,b.dataset.caption||'',b);});
function openRequest(quote,trigger){lastTrigger=trigger;const d=$('#request-dialog'),f=$('form',d);f.reset();$$('.error',f).forEach(x=>x.hidden=true);$$('[aria-invalid]',f).forEach(x=>x.removeAttribute('aria-invalid'));$('.form-result',f).innerHTML='';$('button[type=submit]',f).hidden=false;$('#request-title').textContent=quote?'Коммерческое предложение':'Обсудим ваш будущий дом';$('#request-description').textContent=quote?'Менеджер уточнит участок и пожелания, затем подготовит расчёт при необходимости.':'Менеджер поможет разобраться с проектом и вопросами о строительстве.';const context=$('.form-context',f);let contextText=currentHouse?currentHouse.title:'';if(quote&&currentHouse){const items=[...selectedAddons.values()];contextText+=' · '+money(currentHouse.price==null?null:estimateTotal());if(items.length)contextText+=' · '+items.map(x=>x.name+(x.unit?' × '+x.qty:'')).join('; ');}else if(!currentHouse){const pick=readStorage('focus-design-picker');if(pick)contextText='Подбор: '+(pick.budget?money(Number(pick.budget)):'любой бюджет')+', '+(pick.floors?pick.floors+' этаж(а)':'любая этажность')+', '+(pick.beds||'любое количество')+' спален';}context.textContent=contextText;context.hidden=!contextText;$('button[type=submit]',f).innerHTML=(quote?'Запросить КП':'Получить консультацию')+' '+arrow;d.showModal();}
document.addEventListener('click',e=>{const q=e.target.closest('[data-quote]'),c=e.target.closest('[data-consult]');if(q||c)openRequest(Boolean(q),q||c);});
$$('.request-form').forEach(f=>{const phone=$('[name=phone]',f),err=$('.field .error',f);function validatePhone(){const v=phone.value.replace(/\D/g,'');const ok=(v.length===11&&(v[0]==='7'||v[0]==='8'))||(v.length===10&&v[0]==='9');err.textContent=ok?'':'Укажите российский номер: +7 и ещё 10 цифр.';err.hidden=ok;phone.setAttribute('aria-invalid',String(!ok));return ok;}phone.addEventListener('blur',()=>{if(phone.value.trim())validatePhone();});f.addEventListener('submit',e=>{e.preventDefault();const ok=validatePhone(),consent=$('[name=consent]',f),ce=$('.consent-error',f);ce.hidden=consent.checked;if(!ok){phone.focus();return;}if(!consent.checked){consent.focus();return;}$('.form-result',f).innerHTML='<div class="form-status"><div class="success-mark" aria-hidden="true">✓</div><strong>Так будет выглядеть подтверждение обращения</strong><p style="margin-top:12px">Менеджер свяжется с вами по телефону, уточнит пожелания и при необходимости подготовит смету.</p><p class="demo-note">Это демонстрация. Обращение не отправлено.</p></div>';$('button[type=submit]',f).hidden=true;phone.value='';$('[name=name]',f).value='';$('[name=comment]',f).value='';});});
function readStorage(key){try{return JSON.parse(sessionStorage.getItem(key));}catch{return null;}}
function saveStorage(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));}catch{}}
// Catalog keeps the entire filter state in the URL; browser Back restores it.
if(page==='projects'){
 const form=$('#filters'),sort=$('#sort'),params=new URLSearchParams(location.search);
 for(const n of ['q','budget','floors','beds'])if(params.has(n))form.elements[n].value=params.get(n);
 if(params.has('sort'))sort.value=params.get('sort');
 const normalize=s=>String(s).toLowerCase().replace(/[×xхh.,\s]/g,'');
 function renderCatalog(update=true){
  const q=form.elements.q.value,budget=Number(form.elements.budget.value),floors=Number(form.elements.floors.value),beds=Number(form.elements.beds.value);
  const matches=allHouses.filter(p=>(!q||normalize(p.title).includes(normalize(q)))&&(!budget||(p.price!=null&&p.price<=budget))&&(!floors||p.floors===floors)&&(!beds||(beds===2?p.bed<=2:beds===4?p.bed>=4:p.bed===beds)));
  const families=groupHouseModels(matches,sort.value);
  $('#result-count').textContent='Проектов: '+families.length+' · Вариантов: '+matches.length;
  $('#catalog-results').innerHTML=families.length?families.map(familyCard).join(''):'<div class="empty"><h3>По этим условиям пока нет проектов</h3><p>Увеличьте бюджет или измените этажность и количество спален.</p><button class="btn dark" id="empty-reset">Сбросить фильтры</button></div>';
  $('#empty-reset')?.addEventListener('click',reset);
  if(update){const p=new URLSearchParams({v:'8'});for(const n of ['q','budget','floors','beds'])if(form.elements[n].value)p.set(n,form.elements[n].value);if(sort.value!=='default')p.set('sort',sort.value);history.replaceState(null,'',location.pathname+'?'+p.toString());}
  saveStorage('focus-design-catalog',location.search);
 }
 function reset(){form.reset();sort.value='default';renderCatalog();}
 form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',()=>renderCatalog());sort.addEventListener('change',()=>renderCatalog());$('#reset-filters').addEventListener('click',reset);renderCatalog(false);
}
// Matching never silently relaxes selected conditions.
if(page==='home'){
 let step=0,pick=readStorage('focus-design-picker')||{budget:'',floors:'',beds:''};
 const questions=[{key:'budget',title:'Какой бюджет на дом?',choices:[['6000000','До 6 млн ₽'],['8000000','До 8 млн ₽'],['10000000','До 10 млн ₽'],['12000000','До 12 млн ₽'],['','Пока не определились']]},{key:'floors',title:'Сколько этажей вам подходит?',choices:[['1','Один этаж'],['2','Два этажа'],['','Рассмотрим оба варианта']]},{key:'beds',title:'Сколько нужно спален?',choices:[['2','Одна или две'],['3','Три спальни'],['4','Четыре и больше'],['','Пока не определились']]}];
 function renderPicker(focus=false){const root=$('#picker-area');if(step<3){const q=questions[step];root.innerHTML=`<div class="progress" aria-hidden="true">${questions.map((v,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><p class="picker-step">Вопрос ${step+1} из 3</p><h3 tabindex="-1" id="picker-question">${q.title}</h3><div class="choices">${q.choices.map(([v,l])=>`<button class="choice" data-choice="${v}" aria-pressed="${pick[q.key]===v}">${l}</button>`).join('')}</div><div class="picker-bottom"><button class="icon-btn" id="picker-back" ${step===0?'disabled':''} aria-label="Предыдущий вопрос"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m6-7-7 7 7 7"/></svg></button><button class="btn" id="picker-next">${step===2?'Показать дома':'Следующий вопрос'} ${arrow}</button></div>`;$$('[data-choice]',root).forEach(b=>b.addEventListener('click',()=>{pick[q.key]=b.dataset.choice;saveStorage('focus-design-picker',pick);$$('[data-choice]',root).forEach(v=>v.setAttribute('aria-pressed',String(v===b)));}));$('#picker-back').onclick=()=>{step--;renderPicker(true);};$('#picker-next').onclick=()=>{saveStorage('focus-design-picker',pick);step++;renderPicker(true);};if(focus)$('#picker-question').focus();}else{const budget=Number(pick.budget),floor=Number(pick.floors),bed=Number(pick.beds);const matchedModels=allHouses.filter(p=>(!budget||(p.price!=null&&p.price<=budget))&&(!floor||p.floors===floor)&&(!bed||(bed===2?p.bed<=2:bed===4?p.bed>=4:p.bed===bed)));const list=groupHouseModels(matchedModels);const q=new URLSearchParams({v:'8'});if(pick.budget)q.set('budget',pick.budget);if(pick.floors)q.set('floors',pick.floors);if(pick.beds)q.set('beds',pick.beds);root.innerHTML=`<h3 id="picker-question" tabindex="-1">${list.length?'Подходящих проектов: '+list.length:'Пока нет точных совпадений'}</h3>${list.length?`<div class="project-grid">${list.slice(0,2).map(familyCard).join('')}</div>`:'<p>Попробуйте изменить бюджет или параметры. Также можно обсудить варианты с менеджером.</p>'}<div class="picker-bottom"><button class="btn white" id="picker-restart">Изменить ответы</button>${list.length?`<a class="btn" href="projects.html?${q.toString()}">Все результаты</a>`:'<button class="btn" data-consult>Обсудить подбор</button>'}</div><p class="small" style="margin-top:18px;color:#c4d9d0">Бюджет относится к цене дома в комплектации. Дополнительные работы рассчитываются отдельно.</p>`;$('#picker-restart').onclick=()=>{step=0;renderPicker(true);};if(focus)$('#picker-question').focus();}}
 renderPicker();
}
function estimateTotal(){return (currentHouse?.price||0)+[...selectedAddons.values()].reduce((s,a)=>s+(a.price||0)*a.qty,0);}
if(currentHouse){
 $('#expand-spec')?.addEventListener('click',e=>{const b=e.currentTarget,open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.textContent=open?'Свернуть комплектацию':'Показать всю комплектацию';$$('[data-extra-spec]').forEach(r=>r.hidden=!open);});
 const p=currentHouse,back=$('#catalog-back');const stored=readStorage('focus-design-catalog');if(typeof stored==='string'&&stored.startsWith('?')){const backParams=new URLSearchParams(stored);backParams.set('v','8');back.href='projects.html?'+backParams.toString();}
 $$('[data-gallery]').forEach(b=>b.onclick=()=>{const img=$('#house-main-image');img.src=b.dataset.gallery;img.alt=p.title+', '+b.getAttribute('aria-label');$$('[data-gallery]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
 $('#expand-house').onclick=e=>showImage($('#house-main-image').src,$('#house-main-image').alt,e.currentTarget);
 $$('[data-plan]').forEach(b=>b.onclick=()=>{const plan=p.plans[Number(b.dataset.plan)];$('#plan-image').src=plan.img;$('#plan-image').alt=plan.label;$$('[data-plan]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
 if($('#expand-plan'))$('#expand-plan').onclick=e=>showImage($('#plan-image').src,$('#plan-image').alt,e.currentTarget);
 const groups=[...new Set(p.addons.map(a=>a.group))];
 $('#addon-groups').innerHTML=groups.length?groups.map((g,i)=>`<details class="addon-group" ${i===0?'open':''}><summary>${esc(g)}</summary>${p.addons.filter(a=>a.group===g).map(a=>`<div class="addon-row"><input type="checkbox" id="addon-${a.id}" data-addon="${a.id}"><div class="addon-copy"><div class="addon-title"><label for="addon-${a.id}">${esc(a.name)}</label><button type="button" class="addon-help-toggle" data-addon-help="${a.id}" aria-expanded="false" aria-controls="addon-help-${a.id}" aria-label="Пояснение к услуге: ${esc(a.name)}"><span aria-hidden="true">?</span></button></div><small class="addon-meta">${a.ex?'Выбор одного варианта в этой группе. ':''}${a.unit?'Стоимость за '+esc(a.unit):''}${a.price==null?'Стоимость уточнит менеджер.':''}</small><p class="addon-help" id="addon-help-${a.id}" hidden>${esc(addonHelpText[a.id]||'Дополнительная работа по вашему проекту. Состав и стоимость уточните у менеджера.')}</p></div>${a.unit?`<input class="qty" type="number" min="1" max="100" step="1" value="${Number(a.def)||1}" data-qty="${a.id}" aria-label="Количество: ${esc(a.name)}" disabled>`:''}<strong>${a.price==null?'Уточнить':money(a.price)}</strong></div>`).join('')}</details>`).join(''):'<p class="notice">Перечень дополнительных работ по этому проекту уточнит менеджер.</p>';
 // A help disclosure is separate from the checkbox and never changes the estimate.
 let activeHelp=null;
 function closeAddonHelp(restoreFocus=false){if(!activeHelp)return;const button=activeHelp;document.getElementById(button.getAttribute('aria-controls')).hidden=true;button.setAttribute('aria-expanded','false');activeHelp=null;if(restoreFocus)button.focus();}
 $$('[data-addon-help]').forEach(button=>button.addEventListener('click',()=>{const wasOpen=button.getAttribute('aria-expanded')==='true';closeAddonHelp();if(!wasOpen){document.getElementById(button.getAttribute('aria-controls')).hidden=false;button.setAttribute('aria-expanded','true');activeHelp=button;}}));
 document.addEventListener('click',e=>{if(activeHelp&&!activeHelp.closest('.addon-row').contains(e.target))closeAddonHelp();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeHelp){e.preventDefault();closeAddonHelp(true);}});
 $$('details.addon-group').forEach(group=>group.addEventListener('toggle',()=>{if(!group.open&&activeHelp&&group.contains(activeHelp))closeAddonHelp();}));
 function updateEstimate(){let custom=[...selectedAddons.values()].some(a=>a.price==null);$('#addons-total').textContent=money([...selectedAddons.values()].reduce((s,a)=>s+(a.price||0)*a.qty,0))+(custom?' + уточнение':'');$('#estimate-total').textContent=p.price==null?'По запросу':money(estimateTotal());$('#estimate-note').textContent=custom?'Есть работы с ценой по запросу: они ещё не включены в сумму. Состав и окончательную стоимость уточнит менеджер.':'Состав и окончательную стоимость работ согласуем по вашему участку.';}
 function clearAddon(a){selectedAddons.delete(a.id);const cb=$('#addon-'+a.id);if(cb)cb.checked=false;const qty=$(`[data-qty="${a.id}"]`);if(qty)qty.disabled=true;}
 $$('[data-addon]').forEach(cb=>cb.onchange=()=>{const a=p.addons.find(a=>a.id===cb.dataset.addon);if(cb.checked){if(a.ex)p.addons.filter(x=>x.id!==a.id&&x.ex===a.ex).forEach(clearAddon);const qty=$(`[data-qty="${a.id}"]`);if(qty)qty.disabled=false;selectedAddons.set(a.id,{...a,qty:qty?Number(qty.value):1});}else clearAddon(a);updateEstimate();});
 $$('[data-qty]').forEach(q=>q.oninput=()=>{const n=Math.min(100,Math.max(1,Math.trunc(Number(q.value)||1)));if(selectedAddons.has(q.dataset.qty))selectedAddons.get(q.dataset.qty).qty=n;updateEstimate();});
}
